using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates per-superblock quantizer deltas and segmentation on two real six-frame 128x128 AV1/IVF
/// clips. The first (aomenc perceptual delta-q) codes a quantizer delta at the first block of each
/// superblock, accumulated into a running index that replaces the frame quantizer for dequantization.
/// The second (aomenc cyclic refresh) enables segmentation on the key frame: blocks code a spatially
/// predicted segment id and dequantize with their segment's quantizer delta. Every decoded frame's
/// planes must be exactly equal to dav1d's decoded output.
/// </summary>
public class Av1SegmentationDeltaQDecodeTests
{
    private const string DeltaQClipIvfBase64 =
        "";

    private const string SegmentationClipIvfBase64 =
        "";

    private static readonly string[] DeltaQLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] DeltaQUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] DeltaQVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] SegmentationLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] SegmentationUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] SegmentationVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    [Fact]
    public void DecodeAllFrames_DeltaQClip_MatchesDav1dExactly()
        => DecodeAndCompare(DeltaQClipIvfBase64, DeltaQLumaBase64, DeltaQUBase64, DeltaQVBase64, 6);

    [Fact]
    public void DecodeAllFrames_SegmentationClip_MatchesDav1dExactly()
        => DecodeAndCompare(SegmentationClipIvfBase64, SegmentationLumaBase64, SegmentationUBase64, SegmentationVBase64, 6);

    private static void DecodeAndCompare(string ivfBase64, string[] lumaBase64, string[] uBase64, string[] vBase64, int frameCount)
    {
        using MemoryStream stream = new(Convert.FromBase64String(ivfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(frameCount, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(lumaBase64[i]), Crop(frames[i].Luma));
            Assert.Equal(Convert.FromBase64String(uBase64[i]), Crop(frames[i].ChromaU));
            Assert.Equal(Convert.FromBase64String(vBase64[i]), Crop(frames[i].ChromaV));
        }
    }

    private static byte[] Crop(Av1Plane plane) => Av1TestData.CroppedBytes(plane);
}
